1. explain how the bug occurs, including all code statements that are most likely to lead to the bug and why. 
2. explain how the bug is fixed, including code statements fixing the bug and why. 

You must include one or more code statements in point 1 and 2.
Code statements included in point 1 should be as brief as possible, only include the ones that are most related to the root cause and  the number of code statements may not exceed 3.


Here is the commit message:
md/bitmap: fix GPF in write_page caused by resize race

A General Protection Fault occurs in write_page() during array resize:
RIP: 0010:write_page+0x22b/0x3c0 [md_mod]

This is a use-after-free race between bitmap_daemon_work() and
__bitmap_resize(). The daemon iterates over `bitmap->storage.filemap`
without locking, while the resize path frees that storage via
md_bitmap_file_unmap(). `quiesce()` does not stop the md thread,
allowing concurrent access to freed pages.

Fix by holding `mddev->bitmap_info.mutex` during the bitmap update.

Link: https://lore.kernel.org/linux-raid/20260120102456.25169-1-jinpu.wang@ionos.com
Closes: https://lore.kernel.org/linux-raid/CAMGffE=Mbfp=7xD_hYxXk1PAaCZNSEAVeQGKGy7YF9f2S4=NEA@mail.gmail.com/T/#u
Cc: stable@vger.kernel.org
Fixes: d60b479d177a ("md/bitmap: add bitmap_resize function to allow bitmap resizing.")
Signed-off-by: Jack Wang <jinpu.wang@ionos.com>
Signed-off-by: Yu Kuai <yukuai@fnnas.com>

Here is the root cause:
A use-after-free race condition in `md/bitmap` where `bitmap_daemon_work()` iterates over `bitmap->storage.filemap` without proper locking, while `__bitmap_resize()` simultaneously frees that storage via `md_bitmap_file_unmap()`. The `quiesce()` call does not stop the md thread, allowing concurrent access to freed pages, leading to a general protection fault (GPF) in `write_page()`.

Here is the patch:

 static int __bitmap_resize(struct bitmap *bitmap, sector_t blocks,
 			   int chunksize, bool init)
 {
 	/* If chunk_size is 0, choose an appropriate chunk size.
 	 * Then possibly allocate new storage space.
 	 * Then quiesce, copy bits, replace bitmap, and re-start
 	 *
 	 * This function is called both to set up the initial bitmap
 	 * and to resize the bitmap while the array is active.
 	 * If this happens as a result of the array being resized,
 	 * chunksize will be zero, and we need to choose a suitable
 	 * chunksize, otherwise we use what we are given.
 	 */
 	struct bitmap_storage store;
 	struct bitmap_counts old_counts;
 	unsigned long chunks;
 	sector_t block;
 	sector_t old_blocks, new_blocks;
 	int chunkshift;
 	int ret = 0;
 	long pages;
 	struct bitmap_page *new_bp;

 	if (bitmap->storage.file && !init) {
 		pr_info("md: cannot resize file-based bitmap\n");
 		return -EINVAL;
 	}

 	if (chunksize == 0) {
 		/* If there is enough space, leave the chunk size unchanged,
 		 * else increase by factor of two until there is enough space.
 		 */
 		long bytes;
 		long space = bitmap->mddev->bitmap_info.space;

 		if (space == 0) {
 			/* We don't know how much space there is, so limit
 			 * to current size - in sectors.
 			 */
 			bytes = DIV_ROUND_UP(bitmap->counts.chunks, 8);
 			if (!bitmap->mddev->bitmap_info.external)
 				bytes += sizeof(bitmap_super_t);
 			space = DIV_ROUND_UP(bytes, 512);
 			bitmap->mddev->bitmap_info.space = space;
 		}
 		chunkshift = bitmap->counts.chunkshift;
 		chunkshift--;
 		do {
 			/* 'chunkshift' is shift from block size to chunk size */
 			chunkshift++;
 			chunks = DIV_ROUND_UP_SECTOR_T(blocks, 1 << chunkshift);
 			bytes = DIV_ROUND_UP(chunks, 8);
 			if (!bitmap->mddev->bitmap_info.external)
 				bytes += sizeof(bitmap_super_t);
 		} while (bytes > (space << 9) && (chunkshift + BITMAP_BLOCK_SHIFT) <
 			(BITS_PER_BYTE * sizeof(((bitmap_super_t *)0)->chunksize) - 1));
 	} else
 		chunkshift = ffz(~chunksize) - BITMAP_BLOCK_SHIFT;

 	chunks = DIV_ROUND_UP_SECTOR_T(blocks, 1 << chunkshift);
 	memset(&store, 0, sizeof(store));
 	if (bitmap->mddev->bitmap_info.offset || bitmap->mddev->bitmap_info.file)
 		ret = md_bitmap_storage_alloc(&store, chunks,
 					      !bitmap->mddev->bitmap_info.external,
 					      mddev_is_clustered(bitmap->mddev)
 					      ? bitmap->cluster_slot : 0);
 	if (ret) {
 		md_bitmap_file_unmap(&store);
 		goto err;
 	}

 	pages = DIV_ROUND_UP(chunks, PAGE_COUNTER_RATIO);

 	new_bp = kcalloc(pages, sizeof(*new_bp), GFP_KERNEL);
 	ret = -ENOMEM;
 	if (!new_bp) {
 		md_bitmap_file_unmap(&store);
 		goto err;
 	}

 	if (!init)
 		bitmap->mddev->pers->quiesce(bitmap->mddev, 1);

 	store.file = bitmap->storage.file;
 	bitmap->storage.file = NULL;

 	if (store.sb_page && bitmap->storage.sb_page)
 		memcpy(page_address(store.sb_page),
 		       page_address(bitmap->storage.sb_page),
 		       sizeof(bitmap_super_t));
+	mutex_lock(&bitmap->mddev->bitmap_info.mutex);
 	spin_lock_irq(&bitmap->counts.lock);
 	md_bitmap_file_unmap(&bitmap->storage);
 	bitmap->storage = store;

 	old_counts = bitmap->counts;
 	bitmap->counts.bp = new_bp;
 	bitmap->counts.pages = pages;
 	bitmap->counts.missing_pages = pages;
 	bitmap->counts.chunkshift = chunkshift;
 	bitmap->counts.chunks = chunks;
 	bitmap->mddev->bitmap_info.chunksize = 1UL << (chunkshift +
 						     BITMAP_BLOCK_SHIFT);

 	blocks = min(old_counts.chunks << old_counts.chunkshift,
 		     chunks << chunkshift);

 	/* For cluster raid, need to pre-allocate bitmap */
 	if (mddev_is_clustered(bitmap->mddev)) {
 		unsigned long page;
 		for (page = 0; page < pages; page++) {
 			ret = md_bitmap_checkpage(&bitmap->counts, page, 1, 1);
 			if (ret) {
 				unsigned long k;

 				/* deallocate the page memory */
 				for (k = 0; k < page; k++) {
 					kfree(new_bp[k].map);
 				}
 				kfree(new_bp);

 				/* restore some fields from old_counts */
 				bitmap->counts.bp = old_counts.bp;
 				bitmap->counts.pages = old_counts.pages;
 				bitmap->counts.missing_pages = old_counts.pages;
 				bitmap->counts.chunkshift = old_counts.chunkshift;
 				bitmap->counts.chunks = old_counts.chunks;
 				bitmap->mddev->bitmap_info.chunksize =
 					1UL << (old_counts.chunkshift + BITMAP_BLOCK_SHIFT);
 				blocks = old_counts.chunks << old_counts.chunkshift;
 				pr_warn("Could not pre-allocate in-memory bitmap for cluster raid\n");
 				break;
 			} else
 				bitmap->counts.bp[page].count += 1;
 		}
 	}

 	for (block = 0; block < blocks; ) {
 		bitmap_counter_t *bmc_old, *bmc_new;
 		int set;

 		bmc_old = md_bitmap_get_counter(&old_counts, block, &old_blocks, 0);
 		set = bmc_old && NEEDED(*bmc_old);

 		if (set) {
 			bmc_new = md_bitmap_get_counter(&bitmap->counts, block, &new_blocks, 1);
 			if (bmc_new) {
 				if (*bmc_new == 0) {
 					/* need to set on-disk bits too. */
 					sector_t end = block + new_blocks;
 					sector_t start = block >> chunkshift;

 					start <<= chunkshift;
 					while (start < end) {
 						md_bitmap_file_set_bit(bitmap, block);
 						start += 1 << chunkshift;
 					}
 					*bmc_new = 2;
 					md_bitmap_count_page(&bitmap->counts, block, 1);
 					md_bitmap_set_pending(&bitmap->counts, block);
 				}
 				*bmc_new |= NEEDED_MASK;
 			}
 			if (new_blocks < old_blocks)
 				old_blocks = new_blocks;
 		}
 		block += old_blocks;
 	}

 	if (bitmap->counts.bp != old_counts.bp) {
 		unsigned long k;
 		for (k = 0; k < old_counts.pages; k++)
 			if (!old_counts.bp[k].hijacked)
 				kfree(old_counts.bp[k].map);
 		kfree(old_counts.bp);
 	}

 	if (!init) {
 		int i;
 		while (block < (chunks << chunkshift)) {
 			bitmap_counter_t *bmc;
 			bmc = md_bitmap_get_counter(&bitmap->counts, block, &new_blocks, 1);
 			if (bmc) {
 				/* new space.  It needs to be resynced, so
 				 * we set NEEDED_MASK.
 				 */
 				if (*bmc == 0) {
 					*bmc = NEEDED_MASK | 2;
 					md_bitmap_count_page(&bitmap->counts, block, 1);
 					md_bitmap_set_pending(&bitmap->counts, block);
 				}
 			}
 			block += new_blocks;
 		}
 		for (i = 0; i < bitmap->storage.file_pages; i++)
 			set_page_attr(bitmap, i, BITMAP_PAGE_DIRTY);
 	}
 	spin_unlock_irq(&bitmap->counts.lock);
-
+	mutex_unlock(&bitmap->mddev->bitmap_info.mutex);
 	if (!init) {
 		__bitmap_unplug(bitmap);
 		bitmap->mddev->pers->quiesce(bitmap->mddev, 0);
 	}
 	ret = 0;
 err:
 	return ret;
 }



